p = pathlib.Path("src/main.js")
s = p.read_text()

# ---- pack files map ----
old_files = 'var files={lite:"lite",chill:"chill",focus:"focus",lifeful:"dev",calm:"low-sensory"};'
new_files = 'var files={babylite:"babylite",chill:"chill",FOCUSMAX:"FOCUSMAX",Vibes:"Vibes",calm:"low-sensory",xMAX:"xmax"};'
assert old_files in s
